import{_ as s,o as a,c as t,ag as r}from"./chunks/framework.DQQHyi2x.js";const m=JSON.parse('{"title":"Memory","description":"","frontmatter":{},"headers":[],"relativePath":"features/memory.md","filePath":"features/memory.md"}'),i={name:"features/memory.md"};function o(n,e,l,d,p,h){return a(),t("div",null,[...e[0]||(e[0]=[r(`<h1 id="memory" tabindex="-1">Memory <a class="header-anchor" href="#memory" aria-label="Permalink to &quot;Memory&quot;">​</a></h1><p>View and edit Claude Code&#39;s memory hierarchy — CLAUDE.md files, rules, auto-memory, and imports.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Claude Code uses a layered memory system where instructions are loaded from multiple files at different scopes. The Memory page provides four tabs:</p><ul><li><strong>Hierarchy</strong> — CLAUDE.md files across all scopes</li><li><strong>Rules</strong> — path-scoped rule files</li><li><strong>Auto-Memory</strong> — session-generated memory files</li><li><strong>Imports</strong> — dependency tree of @path references</li></ul><h2 id="how-to-use" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How to Use&quot;">​</a></h2><h3 id="memory-hierarchy" tabindex="-1">Memory Hierarchy <a class="header-anchor" href="#memory-hierarchy" aria-label="Permalink to &quot;Memory Hierarchy&quot;">​</a></h3><p>The Hierarchy tab shows CLAUDE.md files organized by scope (highest to lowest priority):</p><table tabindex="0"><thead><tr><th>Scope</th><th>File</th><th>Description</th></tr></thead><tbody><tr><td><strong>Managed</strong></td><td>Enterprise CLAUDE.md</td><td>Organization-wide policy (read-only)</td></tr><tr><td><strong>User</strong></td><td><code>~/.claude/CLAUDE.md</code></td><td>User preferences and global instructions</td></tr><tr><td><strong>Project</strong></td><td><code>.claude/CLAUDE.md</code> or <code>CLAUDE.md</code></td><td>Team project instructions</td></tr><tr><td><strong>Local</strong></td><td><code>.claude/CLAUDE.local.md</code></td><td>Personal project overrides (not committed)</td></tr></tbody></table><p>Click any memory file card to open the editor with markdown preview. Quick create buttons let you create missing files at any scope.</p><h3 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h3><p>Rules are markdown files in <code>.claude/rules/</code> with optional path-scoped frontmatter:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">TypeScript formatting rules</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">paths</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;src/**/*.ts&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;src/**/*.tsx&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Use strict TypeScript. No \`any\` types.</span></span></code></pre></div><p>Rules only apply when working on files matching the specified paths.</p><h3 id="auto-memory" tabindex="-1">Auto-Memory <a class="header-anchor" href="#auto-memory" aria-label="Permalink to &quot;Auto-Memory&quot;">​</a></h3><p>Session-based memory files that Claude Code auto-generates, stored in <code>~/.claude/projects/{project}/memory/</code>. These persist learnings and preferences across sessions for each project.</p><h3 id="imports" tabindex="-1">Imports <a class="header-anchor" href="#imports" aria-label="Permalink to &quot;Imports&quot;">​</a></h3><p>The Imports tab shows the dependency tree of <code>@path</code> references across memory files:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- In CLAUDE.md --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@./docs/coding-standards.md</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@~/global-rules.md</span></span></code></pre></div><p>Import syntax:</p><ul><li><code>@./relative/path</code> — relative to current file</li><li><code>@~/user/path</code> — relative to home directory</li><li><code>@/absolute/path</code> — absolute path</li></ul><p>The import viewer detects circular references and shows them as warnings.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Memory files are standard markdown. No special Claude Deck configuration needed — the Memory page reads and writes directly to the filesystem.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>Local files</strong> (<code>.claude/CLAUDE.local.md</code>) are for personal overrides — they&#39;re not committed to version control.</li><li><strong>Managed files</strong> are read-only (enterprise-enforced).</li><li>Use <strong>rules</strong> with path patterns to apply instructions only to specific file types.</li><li><strong>Auto-memory</strong> files are auto-generated — edit them to correct or refine Claude&#39;s learned preferences.</li></ul>`,26)])])}const u=s(i,[["render",o]]);export{m as __pageData,u as default};
